
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_hse03_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_hse03", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.310087666523692e+00, -3.248074771053185e+00, -3.161274291959172e+00, -3.041234342383365e+00, -2.878089807691052e+00, -2.661851767982091e+00, -2.385332476384675e+00, -2.048872221317537e+00, -1.663858666175767e+00, -1.251347534838188e+00, -8.552280328147012e-01, -5.945159075003736e-01, -5.216334365447256e-01, -4.332176963016802e-01, -3.202501341661526e-01, -2.100737436826442e-01, -1.216045439072265e-01, -4.946633914029493e-02, -1.081824408569867e-02, -1.216211835714427e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


